<section class="panel commerce-block"><div class="panel-heading"><div><h2>Devis émis</h2><p>Chaque document conserve ses informations et montants d’origine.</p></div></div><?php $count=(int)scalar("SELECT COUNT(*) FROM documents WHERE kind='quote'");$current=max(1,min(max(1,(int)ceil($count/20)),(int)($_GET['p']??1)));$list=all("SELECT * FROM documents WHERE kind='quote' ORDER BY id DESC LIMIT 20 OFFSET ".(($current-1)*20));if(!$list):emptyState('Aucun devis émis.','Enregistrez un brouillon puis émettez sa proposition.');else:?><div class="table-scroll"><table><thead><tr><th>DEVIS</th><th>CLIENT À L’ÉMISSION</th><th>ÉTAT</th><th>VALIDITÉ</th><th class="numeric">TTC</th></tr></thead><tbody><?php foreach($list as $d):$snap=json_decode($d['snapshot'],true);?><tr><td><a class="record-title" href="<?=e(url('document',['id'=>$d['id']]))?>"><?=e($d['number'])?></a><small class="subline"><?=$d['order_id']?e(ref((int)$d['order_id'])):'Sans commande'?></small></td><td><?=e($snap['client']['company'])?></td><td><span class="tag <?=in_array($d['quote_state'],['Accepté','Converti'],true)?'green':'cyan'?>"><?=e(quoteLabel($d))?></span></td><td><?=e($d['valid_until']?:'Non limitée')?></td><td class="numeric"><?=e(money($d['total']))?></td></tr><?php endforeach?></tbody></table></div><?php pagination($count,$current,'quotes',['archived'=>$archived,'dp'=>$draftPage]);endif?></section>
